  readonly Mode?: ProviderMode | undefined;
}): Effect.Effect<Layer.Layer<any, any, never> | undefined> =>
  describeDataPlane(resource).pipe(
    Effect.map((plane) => (plane.kind === "local" ? plane.layer : undefined)),
  );

